import json

import numpy as np
import pytest

from faceAppearance.shDelight import solveShDelight


def syntheticScene(size=40, detail=True):
    y, x = np.mgrid[-1:1:complex(size), -1:1:complex(size)]
    normals = np.stack([0.6 * x, 0.6 * y,
                        np.sqrt(1 - 0.36 * (x * x + y * y))], axis=-1)
    # Independent analytical degree-two lighting, not generated by the module's
    # SH basis helper. Each view has a different light direction and RGB tint.
    directions = np.array([[0.3, -0.5, 0.2], [-0.4, 0.3, -0.1],
                           [0.4, 0.4, -0.2], [-0.3, -0.2, 0.1]])
    shading = np.stack([1 + direction[0] * normals[..., 0]
                        + direction[1] * normals[..., 1]
                        + direction[2] * (3 * normals[..., 2] ** 2 - 1)
                        for direction in directions])[..., None]
    tint = np.array([[1., .95, 1.05], [.95, 1.05, 1.], [1.05, 1., .95], [1., 1., 1.]])
    shading = shading * tint[:, None, None]
    modulation = 1 + (0.1 if detail else 0) * (2 * (np.indices((size, size)).sum(axis=0) % 2) - 1)
    albedo = modulation[..., None] * np.array([.32, .23, .17])
    observations = (albedo * shading).astype(np.float32)
    return observations, np.ones(observations.shape[:3], np.float32), normals, albedo


def normalizedRgb(image):
    return image / image.mean(axis=(-3, -2), keepdims=True)


def testKnownMultiViewLightingRecoversRelativeAlbedoAndKeepsDetail():
    observations, weights, normals, albedo = syntheticScene()
    original = observations.copy()
    result = solveShDelight(observations, weights, normals)
    reference = normalizedRgb(albedo)
    baselineError = np.sqrt(np.mean((normalizedRgb(observations) - reference) ** 2))
    recoveredError = np.sqrt(np.mean((normalizedRgb(result["sharedAlbedo"]) - reference) ** 2))
    assert recoveredError < 0.02
    assert recoveredError < baselineError / 5
    parity = np.indices(albedo.shape[:2]).sum(axis=0) % 2
    recovered = normalizedRgb(result["sharedAlbedo"])
    contrast = recovered[parity == 1].mean() - recovered[parity == 0].mean()
    assert contrast == pytest.approx(0.2, abs=0.025)
    assert result["diagnostics"]["safeCoverageOfInput"] > .99
    assert result["coefficients"].shape == (4, 9, 3)
    np.testing.assert_array_equal(observations, original)
    np.testing.assert_allclose(result["correctedObservations"] * result["shading"], observations, atol=1e-7)
    for item in result["diagnostics"]["trace"]:
        np.testing.assert_allclose(item["albedoMeanRgb"], result["diagnostics"]["gaugeAnchorRgb"], atol=1e-8)
    assert result["diagnostics"]["notGroundTruth"] is True
    json.dumps(result["diagnostics"], allow_nan=False)


def testShOnlyDoesNotUseProvidedOpenDelightColors():
    observations, weights, normals, albedo = syntheticScene(size=20)
    first = solveShDelight(observations, weights, normals, priorAlbedo=albedo * .5, iterations=2)
    second = solveShDelight(observations, weights, normals, priorAlbedo=albedo * 1.8, iterations=2)
    np.testing.assert_array_equal(first["correctedObservations"], second["correctedObservations"])
    assert first["diagnostics"]["priorProvidedButIgnored"]
    assert not first["diagnostics"]["priorUsed"]


def testSoftPriorAnchorsTheGaugeWithoutReplacingHighFrequencyTexture():
    observations, weights, normals, albedo = syntheticScene()
    prior = np.broadcast_to(np.array([.32, .23, .17]), albedo.shape).copy()
    result = solveShDelight(observations, weights, normals, priorAlbedo=prior, mode="shPrior")
    assert np.sqrt(np.mean((result["sharedAlbedo"] - albedo) ** 2)) < .01
    assert result["sharedAlbedo"][..., 0].std() > .02
    assert result["diagnostics"]["priorUsed"]
    assert result["diagnostics"]["gaugeAnchorSource"] == "approximateLinearOpenDelightPrior"
    assert "approximate linear" in result["diagnostics"]["priorEncodingAssumption"]
    shifted = solveShDelight(observations, weights, normals, priorAlbedo=prior * .7,
                            mode="shPrior", iterations=3)
    assert shifted["sharedAlbedo"].mean() < result["sharedAlbedo"].mean() * .8


def testDarkPixelsAndUnsafeLargeDivisionAreExcludedRatherThanClamped():
    observations = np.full((3, 24, 24, 3), .3, np.float32)
    observations[0] = .03  # Bright enough to fit, but needs gain ~10 to match the other views.
    observations[1, 0:3] = .001  # Clear deep shadow: reject before fitting.
    normals = np.zeros((24, 24, 3)); normals[..., 2] = 1
    result = solveShDelight(observations, np.ones(observations.shape[:3]), normals, iterations=4)
    assert not result["validWeights"][0].any()
    assert not result["correctedObservations"][0].any()
    assert not result["validWeights"][1, :3].any()
    assert result["diagnostics"]["views"][0]["unsafeShadingPixelCount"] == 24 * 24
    safe = result["validWeights"] > 0
    assert np.max(1 / result["shading"][safe]) <= 4
    assert result["validWeights"][2].all()


def testClippedPixelsOutliersAndMissingNormalSupportDoNotBecomeEvidence():
    observations, weights, normals, albedo = syntheticScene(size=32, detail=False)
    observations[0, 12:15, 12:15] = 1
    observations[1, 18, 18] = [.85, .12, .12]
    weights[:, :2] = 0
    normals[3:5] = 0
    result = solveShDelight(observations, weights, normals)
    assert not result["validWeights"][0, 12:15, 12:15].any()
    assert not result["validWeights"][:, :2].any()
    assert not result["validWeights"][:, 3:5].any()
    assert not result["correctedObservations"][:, :2].any()
    assert result["diagnostics"]["views"][0]["saturatedRejectedPixelCount"] == 9
    assert result["validWeights"][1, 18, 18] < .15
    expected = albedo[18, 18] / albedo.mean(axis=(0, 1))
    actual = result["sharedAlbedo"][18, 18] / result["sharedAlbedo"][6:].mean(axis=(0, 1))
    np.testing.assert_allclose(actual, expected, atol=.06)


def testCorrectionAboveUnitAlbedoIsNotClampedToWhite():
    observations = np.full((3, 32, 32, 3), .3, np.float32)
    observations[0] = .12
    observations[0, 15, 15] = .9  # Moderate fitted shading would imply reflectance > 1.
    normals = np.zeros((32, 32, 3)); normals[..., 2] = 1
    result = solveShDelight(observations, np.ones(observations.shape[:3]), normals)
    assert not result["validWeights"][0, 15, 15]
    assert not result["correctedObservations"][0, 15, 15].any()
    assert result["diagnostics"]["views"][0]["outOfRangeCorrectionPixelCount"] >= 1


def testReferenceViewFixesColorGaugeWhenAuxiliaryExposureChanges():
    observations = np.full((3, 24, 24, 3), .2, np.float32)
    observations[1:] = .35
    normals = np.zeros((24, 24, 3)); normals[..., 2] = 1
    weights = np.ones(observations.shape[:3])
    first = solveShDelight(observations, weights, normals, gaugeReferenceView=0, iterations=3)
    observations[1:] = .45
    second = solveShDelight(observations, weights, normals, gaugeReferenceView=0, iterations=3)
    np.testing.assert_allclose(first["diagnostics"]["gaugeAnchorRgb"], [.2, .2, .2], atol=1e-6)
    np.testing.assert_array_equal(first["diagnostics"]["gaugeAnchorRgb"], second["diagnostics"]["gaugeAnchorRgb"])
    assert second["diagnostics"]["gaugeAnchorSource"] == "referenceViewRobustObservedRgb"
    assert second["diagnostics"]["gaugeReferenceView"] == 0
    weights[0] = 0
    with pytest.raises(ValueError, match="reference view"):
        solveShDelight(observations, weights, normals, gaugeReferenceView=0)


@pytest.mark.parametrize("reference", [True, -1, 4, 0.5])
def testInvalidReferenceGaugeIsRejected(reference):
    observations, weights, normals, _ = syntheticScene(size=16)
    with pytest.raises(ValueError, match="gaugeReferenceView"):
        solveShDelight(observations, weights, normals, gaugeReferenceView=reference)


@pytest.mark.parametrize("invalid", ["shape", "nan", "range", "weights", "normal", "mode", "prior", "iterations", "empty"])
def testInvalidInputsFailClearly(invalid):
    observations, weights, normals, _ = syntheticScene(size=16)
    options = {}
    if invalid == "shape":
        weights = weights[:, :-1]
    elif invalid == "nan":
        observations[0, 0, 0, 0] = np.nan
    elif invalid == "range":
        observations[0, 0, 0, 0] = 1.1
    elif invalid == "weights":
        weights[0, 0, 0] = -1
    elif invalid == "normal":
        normals[0, 0, 0] = np.inf
    elif invalid == "mode":
        options["mode"] = "guess"
    elif invalid == "prior":
        options["mode"] = "shPrior"
    elif invalid == "iterations":
        options["iterations"] = True
    elif invalid == "empty":
        weights[:] = 0
    with pytest.raises(ValueError):
        solveShDelight(observations, weights, normals, **options)
